<section class="section container"><?php breadcrumbs(['Карта сайта'=>null]) ?><span class="eyebrow">Навигация</span><h1><?= e($page['h1']) ?></h1><p class="lead"><?= e($page['lead']) ?></p><div class="sitemap-grid"><article class="detail-card"><h2>Информация</h2><?php foreach(rows("SELECT * FROM pages WHERE active=1 AND slug NOT IN ('404','success','home','sitemap') AND slug NOT LIKE 'information/%' ORDER BY sort_order") as $p): ?><a href="<?= e(url('/'.$p['slug'])) ?>"><?= e($p['title']) ?></a><?php endforeach ?></article><article class="detail-card"><h2>Каталог</h2><a href="<?= url('/catalog') ?>">Весь каталог</a><?php foreach($allCategories as $c): ?><a class="<?= $c['parent_id']?'child':'' ?>" href="<?= e(url('/catalog/'.$c['slug'])) ?>"><?= e($c['name']) ?></a><?php endforeach ?></article></div></section>
